function(container, apiUrl, tables) {
  let orderItems = [];
  let allProducts = [];
  let demandPredictions = [];

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  // 明日の日付を納期の初期値に設定
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  container.querySelector('#delivery-date').value = tomorrow.toISOString().split('T')[0];

  // 店舗データを読み込み
  function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    const stores = tables.find(t => t.tableName === '店舗マスタ')?.records || [];

    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    stores.forEach(store => {
      if (store.有効フラグ) {
        storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
      }
    });
  }

  // 商品カテゴリを読み込み
  function loadCategories() {
    const categorySelect = container.querySelector('#category-select');
    const products = tables.find(t => t.tableName === '商品マスタ')?.records || [];
    const categories = [...new Set(products.map(p => p.商品カテゴリID))];

    categorySelect.innerHTML = '<option value="">全カテゴリ</option>';
    categories.forEach(categoryId => {
      if (categoryId) {
        categorySelect.innerHTML += `<option value="${categoryId}">カテゴリ${categoryId.slice(-4)}</option>`;
      }
    });
  }

  // 商品一覧を描画
  function renderProducts(products = allProducts) {
    const tbody = container.querySelector('#product-list');
    const storeId = container.querySelector('#store-select').value;

    tbody.innerHTML = products.map(product => {
      const prediction = demandPredictions.find(p => p.商品ID === product.商品ID && p.店舗ID === storeId);
      const predictedQty = prediction ? prediction.予測数量 : 0;
      const stockQty = Math.floor(Math.random() * 100) + 10; // 模擬在庫数

      return `
        <tr data-id="${product.商品ID}">
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>¥${(product.単価 || 0).toLocaleString()}</td>
          <td>${stockQty}</td>
          <td><span class="ai-prediction">${predictedQty}</span></td>
          <td>
            <input type="number" class="input manual-qty" data-product-id="${product.商品ID}" 
                   min="0" max="9999" style="width: 80px;" placeholder="0">
          </td>
          <td>
            <button class="action-btn secondary prediction-reason-btn" data-product-id="${product.商品ID}">
              根拠表示
            </button>
          </td>
          <td>
            <button class="action-btn add-to-order-btn" data-product-id="${product.商品ID}">
              追加
            </button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 発注一覧を描画
  function renderOrderList() {
    const tbody = container.querySelector('#order-list');
    let total = 0;

    tbody.innerHTML = orderItems.map(item => {
      const subtotal = item.quantity * item.unitPrice;
      total += subtotal;

      return `
        <tr data-order-id="${item.productId}">
          <td>${item.productCode}</td>
          <td>${item.productName}</td>
          <td>${item.quantity}</td>
          <td>¥${item.unitPrice.toLocaleString()}</td>
          <td>¥${subtotal.toLocaleString()}</td>
          <td>
            <button class="action-btn secondary remove-from-order-btn" data-product-id="${item.productId}">
              削除
            </button>
          </td>
        </tr>
      `;
    }).join('');

    container.querySelector('#total-amount').textContent = total.toLocaleString();
  }

  // 商品を発注リストに追加
  function addToOrder(productId) {
    const product = allProducts.find(p => p.商品ID === productId);
    if (!product) return;

    const manualQtyInput = container.querySelector(`input[data-product-id="${productId}"]`);
    const quantity = parseInt(manualQtyInput.value) || 0;

    if (quantity <= 0) {
      alert('発注数量を入力してください');
      return;
    }

    // 既存アイテムがあれば数量を更新
    const existingIndex = orderItems.findIndex(item => item.productId === productId);
    if (existingIndex >= 0) {
      orderItems[existingIndex].quantity = quantity;
    } else {
      orderItems.push({
        productId: productId,
        productCode: product.商品コード,
        productName: product.商品名,
        quantity: quantity,
        unitPrice: product.単価 || 0
      });
    }

    manualQtyInput.value = '';
    renderOrderList();
  }

  // 発注リストから削除
  function removeFromOrder(productId) {
    orderItems = orderItems.filter(item => item.productId !== productId);
    renderOrderList();
  }

  // 予測根拠を表示
  function showPredictionReason(productId) {
    const product = allProducts.find(p => p.商品ID === productId);
    const storeId = container.querySelector('#store-select').value;
    const prediction = demandPredictions.find(p => p.商品ID === productId && p.店舗ID === storeId);

    const modal = container.querySelector('#prediction-modal');
    const details = container.querySelector('#prediction-details');

    details.innerHTML = `
      <div style="margin-bottom: 20px;">
        <h4>${product?.商品名 || '商品名不明'}</h4>
        <p class="muted">商品コード: ${product?.商品コード || 'N/A'}</p>
      </div>

      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 20px;">
        <div class="card">
          <div class="card-body">
            <h5>予測結果</h5>
            <p>予測数量: <strong>${prediction?.予測数量 || 0}個</strong></p>
            <p>予測精度: <strong>${prediction?.予測精度 || 85}%</strong></p>
            <p>モデル: ${prediction?.予測モデルバージョン || 'v1.2.3'}</p>
          </div>
        </div>

        <div class="card">
          <div class="card-body">
            <h5>予測要因</h5>
            <ul style="margin: 0; padding-left: 20px;">
              <li>過去3ヶ月の売上トレンド</li>
              <li>季節性要因（${Math.floor(Math.random() * 20) + 90}%）</li>
              <li>曜日別売上パターン</li>
              <li>天候予報の影響</li>
              <li>近隣イベントの影響</li>
            </ul>
          </div>
        </div>
      </div>

      <div class="card" style="margin-top: 20px;">
        <div class="card-body">
          <h5>過去実績データ</h5>
          <p>過去30日平均: ${Math.floor(Math.random() * 50) + 20}個/日</p>
          <p>最大売上: ${Math.floor(Math.random() * 100) + 50}個/日</p>
          <p>最小売上: ${Math.floor(Math.random() * 20) + 5}個/日</p>
        </div>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // 在庫状況を表示
  function showStockStatus() {
    const modal = container.querySelector('#stock-modal');
    const tbody = container.querySelector('#stock-details');

    tbody.innerHTML = allProducts.slice(0, 10).map(product => {
      const currentStock = Math.floor(Math.random() * 100) + 10;
      const safetyStock = Math.floor(Math.random() * 30) + 20;
      let status = '正常';
      let statusColor = 'var(--text)';

      if (currentStock < safetyStock) {
        status = '不足';
        statusColor = '#ff6a00';
      }
      if (currentStock < safetyStock * 0.5) {
        status = '欠品危険';
        statusColor = '#ff0000';
      }

      return `
        <tr>
          <td>${product.商品名}</td>
          <td>${currentStock}</td>
          <td>${safetyStock}</td>
          <td style="color: ${statusColor}; font-weight: bold;">${status}</td>
          <td>${new Date().toLocaleDateString()}</td>
        </tr>
      `;
    }).join('');

    modal.classList.remove('hidden');
  }

  // 過去実績を表示
  function showPastData() {
    const modal = container.querySelector('#past-data-modal');
    modal.classList.remove('hidden');
  }

  // 過去実績データを取得
  function getPastData() {
    const period = container.querySelector('#period-select').value;
    const tbody = container.querySelector('#past-data-details');

    tbody.innerHTML = allProducts.slice(0, 8).map(product => {
      const salesQty = Math.floor(Math.random() * 500) + 100;
      const orderQty = Math.floor(Math.random() * 600) + 120;
      const avgStock = Math.floor(Math.random() * 80) + 30;

      return `
        <tr>
          <td>${product.商品名}</td>
          <td>過去${period}ヶ月</td>
          <td>${salesQty}</td>
          <td>${orderQty}</td>
          <td>${avgStock}</td>
        </tr>
      `;
    }).join('');
  }

  // バリデーション
  function validateForm() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    if (!storeId) {
      alert('店舗を選択してください');
      return false;
    }

    if (!orderDate) {
      alert('発注日付を入力してください');
      return false;
    }

    if (new Date(orderDate) < new Date(today)) {
      alert('発注日に過去の日付は設定できません');
      return false;
    }

    if (!deliveryDate) {
      alert('納期を指定してください');
      return false;
    }

    if (new Date(deliveryDate) < new Date(orderDate)) {
      alert('納期は発注日以降の日付を設定してください');
      return false;
    }

    if (orderItems.length === 0) {
      alert('商品を選択してください');
      return false;
    }

    return true;
  }

  // 発注書作成
  async function createOrder() {
    if (!validateForm()) return;

    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    // 各商品の発注データを作成
    for (const item of orderItems) {
      const orderData = {
        店舗ID: storeId,
        商品ID: item.productId,
        発注日: new Date(orderDate).toISOString(),
        納期予定日: new Date(deliveryDate).toISOString(),
        発注数量: item.quantity,
        発注単価: item.unitPrice,
        発注金額: item.quantity * item.unitPrice,
        発注方法: '手動発注',
        発注ステータス: '発注済',
        仕入先ID: 'supplier-001',
        発注理由: 'AI予測に基づく発注',
        自動発注フラグ: false,
        作成者ID: 'user-001',
        更新者ID: 'user-001'
      };

      const saved = await window.aivicApi.save(7, orderData); // 発注データテーブル
      if (!saved) {
        alert('発注書の作成に失敗しました');
        return;
      }
    }

    alert('発注書が正常に作成されました');
    window.showScreen('scr-1778591852463'); // 発注管理画面に遷移
  }

  // 初期データ読み込み
  async function loadInitialData() {
    // 商品データを読み込み
    const productData = await window.aivicApi.list(2); // 商品マスタ
    if (productData) {
      allProducts = productData.filter(p => p.有効フラグ && p.AI予測対象フラグ);
    } else {
      allProducts = tables.find(t => t.tableName === '商品マスタ')?.records?.filter(p => p.有効フラグ && p.AI予測対象フラグ) || [];
    }

    // 需要予測データを読み込み
    const predictionData = await window.aivicApi.list(9); // 需要予測結果
    if (predictionData) {
      demandPredictions = predictionData;
    } else {
      demandPredictions = tables.find(t => t.tableName === '需要予測結果')?.records || [];
    }

    renderProducts();
  }

  // イベントリスナー設定
  container.querySelector('#category-select').addEventListener('change', (e) => {
    const categoryId = e.target.value;
    const filteredProducts = categoryId ? 
      allProducts.filter(p => p.商品カテゴリID === categoryId) : 
      allProducts;
    renderProducts(filteredProducts);
  });

  container.querySelector('#btn-product-search').addEventListener('click', () => {
    const keyword = container.querySelector('#product-search').value.toLowerCase();
    const filteredProducts = keyword ? 
      allProducts.filter(p => 
        (p.商品名 || '').toLowerCase().includes(keyword) || 
        (p.商品コード || '').toLowerCase().includes(keyword)
      ) : allProducts;
    renderProducts(filteredProducts);
  });

  container.querySelector('#product-search').addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      container.querySelector('#btn-product-search').click();
    }
  });

  // 手動調整数量のバリデーション
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('manual-qty')) {
      const value = parseInt(e.target.value);
      if (value < 0) {
        alert('手動調整数量は0以上の値を入力してください');
        e.target.value = '';
      }
    }
  });

  // イベントデリゲーション
  container.addEventListener('click', (e) => {
    const addBtn = e.target.closest('.add-to-order-btn');
    if (addBtn) {
      addToOrder(addBtn.dataset.productId);
      return;
    }

    const removeBtn = e.target.closest('.remove-from-order-btn');
    if (removeBtn) {
      removeFromOrder(removeBtn.dataset.productId);
      return;
    }

    const reasonBtn = e.target.closest('.prediction-reason-btn');
    if (reasonBtn) {
      showPredictionReason(reasonBtn.dataset.productId);
      return;
    }
  });

  // モーダル関連
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#prediction-modal').classList.add('hidden');
  });

  container.querySelector('#btn-stock-check').addEventListener('click', showStockStatus);
  container.querySelector('#btn-close-stock-modal').addEventListener('click', () => {
    container.querySelector('#stock-modal').classList.add('hidden');
  });

  container.querySelector('#btn-past-data').addEventListener('click', showPastData);
  container.querySelector('#btn-close-past-modal').addEventListener('click', () => {
    container.querySelector('#past-data-modal').classList.add('hidden');
  });

  container.querySelector('#btn-get-past-data').addEventListener('click', getPastData);

  // メインボタン
  container.querySelector('#btn-create-order').addEventListener('click', createOrder);
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    window.showScreen('scr-1778591852463'); // 発注管理画面に戻る
  });

  // 初期化
  loadStores();
  loadCategories();
  loadInitialData();
}
